class Solution {
    public int[][] highestPeak(int[][] isWater){
        int rows=isWater.length,cols=isWater[0].length;
        int[][] height=new int[rows][cols];
        Queue<int[]> queue=new ArrayDeque<>();
        for(int row=0;row<rows;row++)for(int col=0;col<cols;col++)if(isWater[row][col]==1)queue.offer(new int[]{
            row,col
        });
        else height[row][col]=-1;
        int[][] directions={
            {
                1,0
            },{
                -1,0
            },{
                0,1
            },{
                0,-1
            }
        };
        while(!queue.isEmpty()){
            int[] cell=queue.poll();
            for(int[] direction:directions){
                int row=cell[0]+direction[0],col=cell[1]+direction[1];
                if(row>=0&&row<rows&&col>=0&&col<cols&&height[row][col]<0){
                    height[row][col]=height[cell[0]][cell[1]]+1;
                    queue.offer(new int[]{
                        row,col
                    });
                }
            }
        }
        return height;
    }
}

